   1 // StateDrain halts the hart via the Debug Module and populates a
   2 // hybrid_state_v1 with the architectural register file. Reuses
   3 // ResumeDriver's DM register constants and DmiBus interface.
   4 
   5 #pragma once
   6 
   7 #include "hybrid/abstract_command.hpp"
   8 #include "hybrid/dmi_poll.hpp"
   9 #include "hybrid/resume_driver.hpp"
  10 #include "hybrid/state_abi.h"
  11 #include "hybrid/v_regfile_xfer.hpp"
  12 
  13 #include <cstdint>
  14 
  15 namespace hybrid
  16 {
  17 
  18 class StateDrain
  19 {
  20 public:
  21   using RD = ResumeDriver;
  22 
  23   // scratch_gpa: the GUEST address of the V-register transport page (L26: the
  24   // mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the unset
  25   // sentinel; only the V dump sweep consults it. The simulator passes the real
  26   // value from platform.main_memory.
  27   explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset)
  28       : bus_{bus}, scratch_gpa_{scratch_gpa}
  29   {}
  30 
  31   // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
  32   // drain_with_passthrough when the QEMU 1 snapshot is available.
  33   auto drain() -> hybrid_state_v1
  34   {
  35     hybrid_state_v1 state{};
  36     state.magic   = HYBRID_STATE_MAGIC;
  37     state.version = HYBRID_STATE_VERSION;
  38     state.flags   = HYBRID_FLAG_RV64;
  39     halt_and_capture_pc_priv(state);
  40 
  41     for (uint16_t i = 1; i < 32; ++i)
  42       state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
  43 
  44     return state;
  45   }
  46 
  47   // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
  48   // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
  49   // (L20) so post-vsim FP modifications are captured (otherwise the stale
  50   // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set,
  51   // also freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
  52   // and vreg remain pass-through (read-only / too large for DM). L23 mscratch
  53   // and the L24 trap/interrupt CSRs round-trip too (ResumeDriver restores
  54   // them). The Andes/M-ext and L2C re-reads land in later commits.
  55   // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
  56   // contribution would otherwise be discarded as the passthrough preserves
  57   // QEMU1's pre-handoff value.
  58   auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
  59   {
  60     auto state = input;
  61     halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
  62 
  63     // GPRs/FPRs: one abstract register read each. Abstract-only by design,
  64     // like the resume side -- the Program Buffer is reserved for state the
  65     // abstract command space cannot reach (the V regfile, vtype+vl, the L2C
  66     // MMIO window).
  67     for (uint16_t i = 1; i < 32; ++i)
  68       state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
  69 
  70     if (input.flags & HYBRID_FLAG_FP) {
  71       for (uint16_t i = 0; i < 32; ++i)
  72         state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
  73       // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
  74       state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
  75     }
  76 
  77     if (input.flags & HYBRID_FLAG_V) {
  78       state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
  79       state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
  80       state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
  81       state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
  82       state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
