  // producer's reset default, which may legitimately differ from this RTL's
  // (msp_bound all-ones vs 0, milmb.IEN 0 vs 1; see hybrid/write_mask.h).
  static auto wm_live(const hybrid_state_v1& state, int slot) -> bool
  {
    if (!(state.flags & HYBRID_FLAG_WRITE_MASK)) return true;
    return hybrid_wm_test(state.write_mask, static_cast<unsigned>(slot)) != 0;
