TEST_CASE("Andes v3: resume restores mxstatus (prototype) when "
          "HYBRID_FLAG_ANDES set, carrying its value on DATA0/DATA1")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);
  s.flags |= HYBRID_FLAG_ANDES;
  s.andes.mxstatus = 0xA00000001ULL;

  hybrid::ResumeDriver driver(bus, kScratch);
  driver.resume(s);

  // mxstatus (0x7C4) gets a write-COMMAND (bit 16 set) carrying its value on
  // the DATA0/DATA1 written immediately before (same shape as mcache_ctl).
  std::optional<std::size_t> ci;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && (op.value & 0xFFFFu) == hybrid::regno_csr(0x7C4)
        && ((op.value >> 16) & 1u)) { ci = i; break; }
  }
  REQUIRE(ci.has_value());
  REQUIRE(*ci >= 2);
  CHECK(bus.ops[*ci - 2].reg == kData0);
  CHECK(bus.ops[*ci - 2].value == uint32_t(s.andes.mxstatus & 0xFFFFFFFFu));
  CHECK(bus.ops[*ci - 1].reg == kData1);
  CHECK(bus.ops[*ci - 1].value == uint32_t(s.andes.mxstatus >> 32));
}

TEST_CASE("Andes v3: resume issues no mxstatus write without HYBRID_FLAG_ANDES")
{
  RecordingBus bus;
  bus.dmstatus_value = (1u << 9) | (1u << 17);

  auto s = rv64_state(0x80001000, 0);  // no HYBRID_FLAG_ANDES
  s.andes.mxstatus = 0xdead;

  hybrid::ResumeDriver driver(bus, kScratch);
  driver.resume(s);

  const auto ns = cmd_regnos(bus.ops);
  CHECK_FALSE(contains_regno(ns, hybrid::regno_csr(0x7C4)));  // mxstatus
}

