TEST_CASE("Andes v3: drain_with_passthrough re-reads mxstatus (prototype) from "
          "the hart, not the QEMU1 passthrough snapshot")
{
  RecordingBus bus;
  bus.dmstatus_value = kDmstatusHaltedAndAcked;
  // Post-ROI value the measured region left in the hart's mxstatus.
  bus.regfile[hybrid::regno_csr(0x7C4)] = 0x700ULL;

  hybrid_state_v1 input{};
  input.magic   = HYBRID_STATE_MAGIC;
  input.version = HYBRID_STATE_VERSION;
  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES;
  input.priv    = 3;
  input.andes.mxstatus = 0xDEAD;  // stale QEMU1 value; must NOT survive

  hybrid::StateDrain drain(bus, kScratch);
  const auto state = drain.drain_with_passthrough(input);

  CHECK(state.andes.mxstatus == 0x700ULL);
}

TEST_CASE("Andes v3: drain_with_passthrough without HYBRID_FLAG_ANDES leaves "
